<template><Teleport to="body"><div v-show="ask.visible" class="assistant-layer" :style="{zIndex:docked?980:layerZ}" :class="{docked,mobile:isMobile}"><button v-if="!docked" class="assistant-backdrop" aria-label="关闭助手遮罩" @click="close"/><aside ref="panel" class="assistant-panel" role="dialog" aria-label="Ask Awesome" :aria-modal="!docked" tabindex="-1" @keydown="handleKey"><div class="assistant-header"><div class="assistant-identity"><div class="assistant-mark"><img src="/logo.svg" alt=""/></div><div><div class="assistant-title-row"><b>Ask Awesome</b><span>人工确认</span></div><small>材料与证据助手</small></div></div><div class="assistant-tools"><button v-if="canDock" :aria-label="ask.pinned?'取消固定助手':'固定助手'" @click="ask.togglePinned()">{{ ask.pinned?'◇':'◆' }}</button><button aria-label="关闭助手" :disabled="state.busy||loading" @click="close">×</button></div></div><div class="context-strip"><div class="context-signal">当前页面</div><strong>{{ route.meta.title||route.path }}</strong><small v-if="sourceLabel">已载入：{{ sourceLabel }} · {{ loadedAt }}</small></div><div class="assistant-scroll"><details class="page-material-options"><summary>页面材料与快捷问题（可选）</summary><p>主动载入本页材料；切换页面保留本次对话与原材料。</p><el-form v-if="route.path==='/review'" label-position="top"><el-form-item label="复盘材料范围"><el-select v-model="reviewScope" :disabled="state.busy||loading"><el-option v-for="(label,key) in reviewScopes" :key="key" :value="key" :label="label"/></el-select></el-form-item></el-form><el-form v-if="route.path==='/portfolio/cash'" label-position="top"><el-form-item label="资金材料范围"><el-select v-model="cashScope" :disabled="state.busy||loading" aria-label="资金材料范围"><el-option value="current" label="当前筛选的资金流水"/><el-option value="history" label="全部账户的资金修改历史"/></el-select></el-form-item></el-form><el-button :disabled="state.busy||loading" :loading="loading" @click="loadContext">载入当前页面材料</el-button><section v-if="pendingMaterial" class="material-excerpt"><h3>整理长材料</h3><p>原文 {{ pendingMaterial.text.length }} 字符。请从下方原文选取需要讨论的片段；不会自动截断或发送。</p><el-form label-position="top"><el-form-item label="原始页面材料"><el-input :model-value="pendingMaterial.text" type="textarea" :rows="6" readonly/></el-form-item><el-form-item label="选取的材料片段"><el-input v-model="excerpt" type="textarea" :rows="6" maxlength="18000" show-word-limit :disabled="state.busy||loading"/></el-form-item></el-form><el-button :disabled="state.busy||loading||!excerpt.trim()" @click="applyExcerpt">采用选取片段</el-button><el-button :disabled="state.busy||loading" @click="pendingMaterial=null">取消整理</el-button></section><p v-if="error" role="alert">{{ error }}</p><details v-if="source"><summary>核对载入的材料</summary><pre>{{ source }}</pre></details><div class="prompt-list"><button v-for="question in suggestions" :key="question" :disabled="state.busy||loading" @click="fillQuestion(question)">{{ question }}</button></div></details></div><Conversation ref="assistant" :source-context="source" :external-busy="loading" @state="state=$event" @connection-settings="close"/></aside></div></Teleport></template>
<script setup lang="ts">
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessageBox,useZIndex} from 'element-plus'
import {useAskStore} from '@/stores/ask'
import {readPageMaterial} from '@/api/pageMaterial'
import Conversation from './Conversation.vue'
const {nextZIndex}=useZIndex(),layerZ=ref(2000)
const props=defineProps<{canDock:boolean;isMobile:boolean}>(),panel=ref<HTMLElement|null>(null),assistant=ref<InstanceType<typeof Conversation>|null>(null)
let previousFocus:HTMLElement|null=null
const ask=useAskStore(),route=useRoute(),source=ref(''),sourceLabel=ref(''),loadedAt=ref(''),loading=ref(false),error=ref(''),state=ref({busy:false,preview:false,result:false,failed:false,dirty:false});let live=true
const pendingMaterial=ref<{text:string;path:string;label:string;captured_at:string}|null>(null),excerpt=ref('')
const cashScope=ref('current')
const reviewScope=ref(''),reviewScopes={investment_journal:'当前筛选的投资日记',manual:'当前筛选的人工复盘',daily:'当前筛选的日报日记',journal:'教练复核日记',coach:'当前教练报告',period:'当前周期报告'}
const docked=computed(()=>props.canDock&&ask.pinned)
const suggestions=computed(()=>route.path.startsWith('/plan')?['检查计划的触发与停止条件','指出当前试算的假设和缺口']:route.path.startsWith('/review')?['分别复核决策过程和结果','哪些改进需要更多证据']:['解释当前材料里的事实与推断','列出缺失证据与反方观点'])
async function fillQuestion(question:string){if(state.value.dirty){try{await ElMessageBox.confirm('替换输入框中当前问题？材料和对话记录保留。','填入快捷问题',{confirmButtonText:'替换问题',cancelButtonText:'取消'})}catch{return}}assistant.value?.setQuestion(question)}
function close(){if(!state.value.busy&&!loading.value)ask.close()}
watch(()=>ask.visible,async visible=>{if(visible){layerZ.value=nextZIndex();previousFocus=document.activeElement as HTMLElement;await nextTick();panel.value?.focus()}else{previousFocus?.isConnected&&previousFocus.focus()} })
function handleKey(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();close();return}if(event.key!=='Tab'||docked.value)return;const items=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href],[tabindex="0"]')||[]).filter(e=>e.getClientRects().length);const first=items[0],last=items[items.length-1];if(!first){event.preventDefault();panel.value?.focus();return}if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}

async function loadContext(){if(state.value.busy||loading.value)return;if(pendingMaterial.value&&excerpt.value){try{await ElMessageBox.confirm('重新载入会清除正在整理的片段。','重新载入材料',{confirmButtonText:'重新载入',cancelButtonText:'保留片段'})}catch{return}}loading.value=true;error.value='';const path=route.path,label=String(route.meta.title||path)+(route.path==='/review'&&reviewScope.value?' · '+reviewScopes[reviewScope.value as keyof typeof reviewScopes]:route.path==='/portfolio/cash'?' · '+(cashScope.value==='history'?'全部账户的资金修改历史':'当前筛选的资金流水'):'');try{let payload:unknown
if(path.startsWith('/settings')||path.startsWith('/academy'))throw Error('此页面不自动提取账号、路径、密钥或学习内容。请在待发送上下文中自行填写需要讨论的片段。')
const pageMaterial=readPageMaterial(path,path==='/portfolio/cash'?cashScope.value:reviewScope.value)
if(!pageMaterial)throw Error('页面材料尚未就绪，请先在页面载入或选择报告。')
payload=pageMaterial.material
const now=new Date().toISOString(),text=JSON.stringify({page:path,label,captured_at:now,material:payload},null,2);if(!live)return;if(text.length>20000){pendingMaterial.value={text,path,label,captured_at:now};excerpt.value='';return}await installMaterial(text,label,now)
}catch(e){error.value=e instanceof Error?e.message:'读取失败，原材料保留'}finally{loading.value=false}}
async function installMaterial(text:string,label:string,now:string){if(state.value.busy)return false;if(assistant.value&&!await assistant.value.confirmMaterialChange())return false;if(!live)return false;source.value=text;sourceLabel.value=label;loadedAt.value=new Date(now).toLocaleString('zh-CN');pendingMaterial.value=null;return true}
async function applyExcerpt(){if(state.value.busy||loading.value||!pendingMaterial.value||!excerpt.value.trim())return;const p=pendingMaterial.value,text=JSON.stringify({page:p.path,label:p.label,captured_at:p.captured_at,selection:'user_selected_excerpt_not_complete_source',original_characters:p.text.length,material_excerpt:excerpt.value},null,2);if(text.length>20000){error.value='选取片段加来源说明超过20000字符，请继续缩短。';return}loading.value=true;error.value='';try{await installMaterial(text,p.label+' · 用户选取片段',p.captured_at)}finally{loading.value=false}}
const beforeUnload=(e:BeforeUnloadEvent)=>{if(state.value.dirty||state.value.busy||loading.value||pendingMaterial.value&&excerpt.value){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{live=false;ask.close();window.removeEventListener('beforeunload',beforeUnload)})
</script>
